<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {api} from '../api';import Modal from './Modal.vue';
const props=defineProps<{record:any}>(),emit=defineEmits<{close:[]}>(),data=ref<any>(null),loading=ref(false),error=ref(''),page=ref(1),pages=computed(()=>Math.max(1,Math.ceil((data.value?.total||0)/20)));
function time(value:string){return new Date(value).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',hour12:false});}
async function load(next=page.value){loading.value=true;error.value='';data.value=null;try{data.value=await api(`transfers/history?id=${props.record.id}&page=${next}`);page.value=next;}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
onMounted(()=>load());
</script>
<template><Modal title="調店更正紀錄" @cancel="emit('close')"><p><strong>{{record.employee_code}} {{record.employee_name}}</strong></p><p>{{record.from_store?.store_name}} → {{record.to_store?.store_name}}</p><p v-if="loading" role="status">正在載入更正紀錄…</p><p v-if="error" class="notice error" role="alert">{{error}}</p><template v-if="data"><section v-if="data.legacy" class="legacy"><h3>舊版最後更正資訊</h3><p>更正為 {{data.legacy.new_date}} · {{data.legacy.actor_name}}</p><p>{{time(data.legacy.created_at)}}</p><p class="reason">{{data.legacy.reason||'未提供原因'}}</p><p>此筆未保留完整歷次紀錄，無法顯示更正前日期。</p></section><p>已保存 {{data.total}} 次更正</p><ol v-if="data.rows.length" class="history"><li v-for="r in data.rows" :key="r.request_id"><h3>{{r.old_date}} → {{r.new_date}}</h3><p class="meta">{{r.actor_name}} · {{time(r.created_at)}}</p><p class="reason">{{r.reason}}</p></li></ol><p v-else>此頁沒有已保存的更正紀錄。</p><div v-if="pages>1" class="pagination"><button :disabled="page<=1||loading" @click="load(page-1)">上一頁</button><span>第 {{page}} / {{pages}} 頁</span><button :disabled="page>=pages||loading" @click="load(page+1)">下一頁</button></div></template><div class="dialog-actions"><button :disabled="loading" @click="load(1)">重新載入</button><button @click="emit('close')">關閉</button></div></Modal></template>
<style scoped>.history{list-style:none;padding:0;max-height:420px;overflow:auto}.history li{border-top:1px solid var(--line);padding:16px 0}.history h3,.legacy h3{font-size:15px;margin:0}.meta{color:var(--muted);font-size:13px}.reason{white-space:pre-wrap;overflow-wrap:anywhere}.legacy{border-left:3px solid var(--primary);padding-left:12px}.pagination{display:flex;gap:12px;align-items:center;justify-content:space-between}@media(max-width:600px){.history{max-height:max(120px,min(340px,calc(100dvh - 480px)))}}</style>
